do $$ begin if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='messages') then alter publication supabase_realtime add table public.messages; end if; if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='message_receipts') then alter publication supabase_realtime add table public.message_receipts; end if; if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='social_posts') then alter publication supabase_realtime add table public.social_posts; end if; if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='social_reactions') then alter publication supabase_realtime add table public.social_reactions; end if; if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='social_comments') then alter publication supabase_realtime add table public.social_comments; end if; if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='social_location_shares') then alter publication supabase_realtime add table public.social_location_shares; end if; end $$; alter table public.messages replica identity full; alter table public.message_receipts replica identity full; alter table public.social_posts replica identity full; alter table public.social_reactions replica identity full; alter table public.social_comments replica identity full; alter table public.social_location_shares replica identity full;